public void updateAccountBalances(Long fromId, Long toId, BigDecimal amount) {
    // Always sort resource acquisition by ID to prevent circular wait conditions
    Long first = Math.min(fromId, toId);
    Long second = Math.max(fromId, toId);

    try {
        repository.lockAccount(first);
        repository.lockAccount(second);
        repository.transfer(fromId, toId, amount);
    } catch (DeadlockLoserDataAccessException e) {
        // Production code must implement retry logic with exponential backoff
        retryTransaction();
    }
}
